INSERT INTO dbo.ValuationConversationLog (SessionID, MessageOrder, Sender, MessageText) VALUES
(1, 1, N'Bot', N'Hi! Let''s get an estimate for your trade-in. What''s the make, model, and year of your vehicle?'),
(1, 2, N'Customer', N'2019 Volkswagen Polo.'),
(1, 3, N'Bot', N'Thanks. Roughly how many kilometres has it done, and has it ever been in an accident?'),
(1, 4, N'Customer', N'About 85,000 km, no accidents.'),
(1, 5, N'Bot', N'Great. Any dents or scratches I should know about, and are there any chips or cracks on the windscreen?'),
(1, 6, N'Customer', N'Just a small dent about the size of a golf ball on the rear door, windscreen is fine.'),
(1, 7, N'Bot', N'Has the car been resprayed, or does it have any aftermarket parts like wheels or a sound system - and if so, was that done by a reputable shop or done informally?'),
(1, 8, N'Customer', N'Aftermarket wheels, fitted by a reputable tyre shop.'),
(1, 9, N'Bot', N'Thanks - based on this, your estimated trade-in value is R142,000-R151,000. Would you also like to add a cash deposit toward your next vehicle? A consultant will confirm the final figure with you shortly.');
